        state.gpr[Register::Rdx as usize] = 9;
        let before = state.clone();
        let mut memory = CasMemory::new(code, 1);
        memory.read_fault = Some(fault.clone());
        let result = run_cas_set(&mut state, &mut memory).unwrap();
